import{_ as a,a0 as n,w as u,s as p,ao as l,I as s,x as r,a1 as o,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse(`{"title":"Linux常见问题解答--如何修复 tar：由于前一个错误导致于失败状态中退出  | LCTT x X-CMD","titleTemplate":false,"description":"Linux常见问题解答--如何修复 tar：由于前一个错误导致于失败状态中退出  | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux常见问题解答--如何修复 tar：由于前一个错误导致于失败状态中退出  | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux常见问题解答--如何修复 tar：由于前一个错误导致于失败状态中退出  | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150709 Linux FAQs with Answers--How to fix 'tar--Exiting with failure status due to previous errors'","title":"Linux常见问题解答--如何修复 tar：由于前一个错误导致于失败状态中退出 ","tag":"201507","desc":""},"relativePath":"201507/20150709 Linux FAQs with Answers--How to fix 'tar--Exiting with failure status due to previous errors'.md","filePath":"[post].md"}`),d={name:"201507/20150709 Linux FAQs with Answers--How to fix 'tar--Exiting with failure status due to previous errors'.md"};function x(f,t,m,_,g,w){const e=n("Link");return u(),p("div",null,[t[13]||(t[13]=l(`<h1 id="linux常见问题解答-如何修复-tar-由于前一个错误导致于失败状态中退出" tabindex="-1">Linux常见问题解答--如何修复&quot;tar：由于前一个错误导致于失败状态中退出&quot; <a class="header-anchor" href="#linux常见问题解答-如何修复-tar-由于前一个错误导致于失败状态中退出" aria-label="Permalink to “Linux常见问题解答--如何修复tar：由于前一个错误导致于失败状态中退出”">​</a></h1><blockquote><p><strong>问题</strong>: 当我想试着用tar命令来创建一个压缩文件时，总在执行过程中失败，并且抛出一个错误说明&quot;tar：由于前一个错误导致于失败状态中退出&quot;(&quot;Exiting with failure status due to previous errors&quot;). 什么导致这个错误的发生，要如何解决？</p></blockquote><p><img src="https://farm9.staticflickr.com/8863/17631029953_1140fe2dd3_b.jpg" alt=""></p><p>如果当你执行tar命令时，遇到了下面的错误，那么最有可能的原因是对于你想用tar命令压缩的某个文件中，你并不具备其读权限。</p><pre><code>tar: Exiting with failure status due to previous errors
</code></pre><p>那么我们要如何确定引起错误的这个（些）文件呢？或者如何确定其它的错误根源？</p><p>事实上tar命令应该会打印出所谓的“上一个错误”(&quot;previous errors&quot;)到底是什么错误，但是如果你让tar运行在详细模式（即verbose mode，例如, -cvf)，那么你会很容易错失这些信息。要找到这些信息，你可以像下面那样，把tar的标准输出（stdout)信息过滤掉。</p><pre><code>$ tar cvzfz backup.tgz my_program/ &gt; /dev/null
</code></pre><p>然后你会看到tar输出的标准错误(stderr)信息。（LCTT 译注：自然，不用 v 参数也可以。）</p><pre><code>tar: my_program/src/lib/.conf.db.~lock~: Cannot open: Permission denied
tar: Exiting with failure status due to previous errors
</code></pre><p>你可以从上面的例子中看到，引起错误的原因的确是“读权限不允许”（denied read permission.)要解决这个问题，只要简单地更改(或移除)问题文件的权限，然后重新执行tar命令即可。</p><hr>`,12)),s("p",null,[t[1]||(t[1]=r("via: ",-1)),o(e,{href:"http://ask.xmodulo.com/tar-exiting-with-failure-status-due-to-previous-errors.html"},{default:i(()=>[...t[0]||(t[0]=[r("http://ask.xmodulo.com/tar-exiting-with-failure-status-due-to-previous-errors.html",-1)])]),_:1})]),s("p",null,[t[5]||(t[5]=r("作者：",-1)),o(e,{href:"http://ask.xmodulo.com/author/nanni"},{default:i(()=>[...t[2]||(t[2]=[r("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=r(" 译者：",-1)),o(e,{href:"https://github.com/XLCYun"},{default:i(()=>[...t[3]||(t[3]=[r("XLCYun(袖里藏云)",-1)])]),_:1}),t[7]||(t[7]=r(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[4]||(t[4]=[r("wxy",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=r("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[8]||(t[8]=[r("LCTT",-1)])]),_:1}),t[11]||(t[11]=r(" 原创翻译，",-1)),o(e,{href:"https://linux.cn/"},{default:i(()=>[...t[9]||(t[9]=[r("Linux中国",-1)])]),_:1}),t[12]||(t[12]=r(" 荣誉推出",-1))])])}const v=a(d,[["render",x]]);export{C as __pageData,v as default};
